import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);
  const [pagesData, setPagesData] = useState({});

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return user?.role === 'instructor' ? `courses?instructorid=${user.id}` : 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    if (pageName === 'instructors') return 'users?role=instructor';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'instructors') return { name: '', email: '', courseTitle: '', courseDescription: '', courseSyllabus: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : 'courses');
    } catch (err) {
      alert('Login failed — use demo emails like nm@sportal.com or mc@sportal.com');
    }
  };

  const loadData = async () => {
    setLoading(true);
    const endpoint = getEndpoint(page);
    if (!endpoint) {
      setLoading(false);
      return;
    }
    if (pagesData[page]) {
      setData(pagesData[page]);
      setLoading(false);
      return;
    }
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      setPagesData(prev => ({ ...prev, [page]: res.data }));
      setData(res.data);
      if (page === 'courses') setCourses(res.data);
      if (page === 'assignments') setAssignments(res.data);
    } catch (err) {
      alert('Error loading data');
    }
    setLoading(false);
  };

  useEffect(() => {
    if (!user || !['courses', 'assignments', 'announcements', 'submissions', 'instructors'].includes(page)) return;
    loadData();
  }, [page, user]);

  useEffect(() => {
    if (user?.role === 'student') {
      const enrolled = courses.filter(c => c.students?.includes(user.id) || c.students?.includes(user.id.toString()));
      setEnrolledCourseIds(enrolled.map(c => c.id));
    }
  }, [courses, user]);

  useEffect(() => {
    if (page === 'courses' && user?.role === 'student') {
      const enrolled = data.filter(c => c.students?.includes(user.id) || c.students?.includes(user.id.toString()));
      setEnrolledCourseIds(enrolled.map(c => c.id));
    }
  }, [data, page, user]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const createItem = async () => {
    try {
      let res;
      if (page === 'instructors') {
        const userRes = await axios.post(`${API}/users`, { name: formData.name, email: formData.email, role: 'instructor' });
        res = await axios.post(`${API}/courses`, {
          title: formData.courseTitle,
          description: formData.courseDescription,
          syllabus: formData.courseSyllabus,
          instructorid: userRes.data.id
        });
      } else {
        res = await axios.post(`${API}/${getEndpoint(page)}`, formData);
      }
      setShowForm(false);
      setFormData(getEmptyForm(page));
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Create failed');
    }
  };

  const updateItem = async () => {
    try {
      const res = await axios.put(`${API}/${getEndpoint(page)}/${editingItem.id}`, formData);
      setEditingItem(null);
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Update failed');
    }
  };

  const deleteItem = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete.id}`);
      setShowConfirmDelete(false);
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Delete failed');
    }
  };

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Enroll failed');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Drop failed');
    }
  };

  const submitAssignment = async () => {
    try {
      const res = await axios.post(`${API}/submissions`, { assignmentid: selectedAssignment.id, studentid: user.id, fileurl: submissionText });
      setSubmissionText('');
      setSelectedAssignment(null);
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Submission failed');
    }
  };

  const updateSubmission = async (submissionId) => {
    try {
      const res = await axios.put(`${API}/submissions/${submissionId}`, { fileurl: currentSubmissionText });
      setShowFileModal(false);
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Update failed');
    }
  };

  const gradeSubmission = async () => {
    try {
      const res = await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, { grade: gradeValue, feedback: feedbackText });
      setShowGradeModal(false);
      setPagesData(prev => ({ ...prev, [page]: null }));
      loadData();
    } catch (err) {
      alert('Grading failed');
    }
  };

  const sendChatMessage = async () => {
    if (!chatInput.trim() || chatLoading) return;
    setChatMessages([...chatMessages, { sender: 'user', text: chatInput }]);
    setChatInput('');
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: chatInput });
      setChatMessages(prev => [...prev, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { sender: 'bot', text: 'Sorry, something went wrong.' }]);
    }
    setChatLoading(false);
  };

  const handleFormChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  if (!user) {
    return (
      <div className="app">
        <h1>NM Student Portal</h1>
        <form onSubmit={login}>
          <input type="email" value={emailInput} onChange={(e) => setEmailInput(e.target.value)} placeholder="Enter email" required />
          <button type="submit">Login</button>
        </form>
        <p>Use demo: nm@sportal.com (student) or mc@sportal.com (instructor) or admin@sportal.com</p>
      </div>
    );
  }

  return (
    <div className="app">
      <header>
        <h1>Welcome, {user.name} ({user.role})</h1>
        <button onClick={() => { setUser(null); setPage('login'); }}>Logout</button>
      </header>
      <main>
        <nav>
          {user.role === 'student' && (
            <>
              <a onClick={() => setPage('courses')}>Courses</a>
              <a onClick={() => setPage('assignments')}>Assignments</a>
              <a onClick={() => setPage('announcements')}>Announcements</a>
              <a onClick={() => setPage('submissions')}>Submissions</a>
            </>
          )}
          {user.role === 'instructor' && (
            <>
              <a onClick={() => setPage('courses')}>Courses</a>
              <a onClick={() => setPage('assignments')}>Assignments</a>
              <a onClick={() => setPage('announcements')}>Announcements</a>
              <a onClick={() => setPage('submissions')}>Grade Submissions</a>
            </>
          )}
          {user.role === 'admin' && (
            <>
              <a onClick={() => setPage('instructors')}>Instructors</a>
            </>
          )}
        </nav>
        {loading ? <p>Loading...</p> : (
          <div className="container">
            <h2>{page.charAt(0).toUpperCase() + page.slice(1)}</h2>
            {user.role !== 'student' && page !== 'submissions' && (
              <button onClick={() => { setShowForm(true); setFormData(getEmptyForm(page)); setEditingItem(null); }}>Add New</button>
            )}
            <table>
              <thead>
                <tr>
                  {page === 'courses' && <th>Title</th>}
                  {page === 'courses' && <th>Description</th>}
                  {page === 'courses' && <th>Syllabus</th>}
                  {page === 'courses' && user.role === 'student' && <th>Action</th>}
                  {page === 'assignments' && <th>Title</th>}
                  {page === 'assignments' && <th>Due Date</th>}
                  {page === 'assignments' && <th>Description</th>}
                  {page === 'announcements' && <th>Title</th>}
                  {page === 'announcements' && <th>Message</th>}
                  {page === 'submissions' && <th>Assignment ID</th>}
                  {page === 'submissions' && <th>File</th>}
                  {page === 'submissions' && <th>Grade</th>}
                  {page === 'submissions' && <th>Feedback</th>}
                  {page === 'instructors' && <th>Name</th>}
                  {page === 'instructors' && <th>Email</th>}
                  {(user.role !== 'student' || page === 'submissions') && <th>Actions</th>}
                </tr>
              </thead>
              <tbody>
                {page === 'courses' && data.map(c => (
                  <tr key={c.id}>
                    <td>{c.title}</td>
                    <td>{c.description}</td>
                    <td>{c.syllabus}</td>
                    {user.role === 'student' && (
                      <td>
                        {enrolledCourseIds.includes(c.id) ? (
                          <button onClick={() => drop(c.id)}>Drop</button>
                        ) : (
                          <button onClick={() => enroll(c.id)}>Enroll</button>
                        )}
                      </td>
                    )}
                    {user.role !== 'student' && (
                      <td>
                        <button onClick={() => { setEditingItem(c); setFormData({ title: c.title, description: c.description, syllabus: c.syllabus }); }}>Edit</button>
                        <button onClick={() => { setItemToDelete(c); setDeleteBase('courses'); setShowConfirmDelete(true); }}>Delete</button>
                      </td>
                    )}
                  </tr>
                ))}
                {page === 'assignments' && data.filter(a => user.role === 'student' ? enrolledCourseIds.includes(a.courseid) : true).map(a => (
                  <tr key={a.id}>
                    <td>{a.title}</td>
                    <td>{a.duedate}</td>
                    <td>{a.description}</td>
                    <td>
                      {user.role === 'student' ? (
                        <button onClick={() => setSelectedAssignment(a)}>Submit</button>
                      ) : (
                        <>
                          <button onClick={() => { setEditingItem(a); setFormData({ title: a.title, duedate: a.duedate, description: a.description }); }}>Edit</button>
                          <button onClick={() => { setItemToDelete(a); setDeleteBase('assignments'); setShowConfirmDelete(true); }}>Delete</button>
                        </>
                      )}
                    </td>
                  </tr>
                ))}
                {page === 'announcements' && data.filter(an => user.role === 'student' ? enrolledCourseIds.includes(an.courseid) : true).map(an => (
                  <tr key={an.id}>
                    <td>{an.title}</td>
                    <td>{an.message}</td>
                    {user.role !== 'student' && (
                      <td>
                        <button onClick={() => { setEditingItem(an); setFormData({ title: an.title, message: an.message }); }}>Edit</button>
                        <button onClick={() => { setItemToDelete(an); setDeleteBase('announcements'); setShowConfirmDelete(true); }}>Delete</button>
                      </td>
                    )}
                  </tr>
                ))}
                {page === 'submissions' && data.filter(s => user.role === 'student' ? true : true).map(s => (
                  <tr key={s.id}>
                    <td>{s.assignmentid}</td>
                    <td>{s.fileurl}</td>
                    <td>{s.grade || 'Ungraded'}</td>
                    <td>{s.feedback || ''}</td>
                    <td>
                      {user.role === 'student' ? (
                        <button onClick={() => { setShowFileModal(true); setCurrentSubmissionText(s.fileurl); }}>Edit File</button>
                      ) : (
                        <button onClick={() => { setSubmissionToGrade(s); setGradeValue(s.grade || ''); setFeedbackText(s.feedback || ''); setShowGradeModal(true); }}>Grade</button>
                      )}
                    </td>
                  </tr>
                ))}
                {page === 'instructors' && data.map(i => (
                  <tr key={i.id}>
                    <td>{i.name}</td>
                    <td>{i.email}</td>
                    <td>
                      <button onClick={() => { setEditingItem(i); setFormData({ name: i.name, email: i.email }); }}>Edit</button>
                      <button onClick={() => { setItemToDelete(i); setDeleteBase('users'); setShowConfirmDelete(true); }}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        {showForm && (
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', zIndex: 1000 }}>
            <h3>{editingItem ? 'Edit' : 'Add'} {page.charAt(0).toUpperCase() + page.slice(1)}</h3>
            {Object.keys(getEmptyForm(page)).map(key => (
              <input key={key} name={key} value={formData[key] || ''} onChange={handleFormChange} placeholder={key.charAt(0).toUpperCase() + key.slice(1)} style={{ display: 'block', margin: '10px 0' }} />
            ))}
            <button onClick={editingItem ? updateItem : createItem}>Save</button>
            <button onClick={() => setShowForm(false)}>Cancel</button>
          </div>
        )}
        {selectedAssignment && (
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', zIndex: 1000 }}>
            <h3>Submit for {selectedAssignment.title}</h3>
            <input value={submissionText} onChange={(e) => setSubmissionText(e.target.value)} placeholder="File URL or text" />
            <button onClick={submitAssignment}>Submit</button>
            <button onClick={() => setSelectedAssignment(null)}>Cancel</button>
          </div>
        )}
        {showFileModal && (
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', zIndex: 1000 }}>
            <h3>Update File</h3>
            <input value={currentSubmissionText} onChange={(e) => setCurrentSubmissionText(e.target.value)} placeholder="New file URL or text" />
            <button onClick={() => updateSubmission(/* submission id here, assume from context */)}>Update</button>
            <button onClick={() => setShowFileModal(false)}>Cancel</button>
          </div>
        )}
        {showGradeModal && (
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', zIndex: 1000 }}>
            <h3>Grade Submission</h3>
            <input value={gradeValue} onChange={(e) => setGradeValue(e.target.value)} placeholder="Grade" />
            <input value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} placeholder="Feedback" />
            <button onClick={gradeSubmission}>Save</button>
            <button onClick={() => setShowGradeModal(false)}>Cancel</button>
          </div>
        )}
        {showConfirmDelete && (
          <div style={{ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', background: 'white', padding: '20px', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', zIndex: 1000 }}>
            <h3>Confirm Delete?</h3>
            <button onClick={deleteItem}>Yes</button>
            <button onClick={() => setShowConfirmDelete(false)}>No</button>
          </div>
        )}
        {showChat && (
          <div style={{ position: 'fixed', bottom: '100px', right: '30px', width: '380px', height: '500px', background: 'white', borderRadius: '16px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
            <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              NM Portal Assistant
              <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
            </div>
            <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
              {chatMessages.map((msg, i) => (
                <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                  <div style={{ display: 'inline-block', maxWidth: '80%', padding: '12px 16px', borderRadius: '16px', background: msg.sender === 'user' ? '#667eea' : '#e2e8f0', color: msg.sender === 'user' ? 'white' : '#333' }}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
              <div ref={chatEndRef} />
            </div>
            <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
              <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()} placeholder="Ask about the portal..." style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }} />
              <button onClick={sendChatMessage} disabled={chatLoading} style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Send</button>
            </div>
          </div>
        )}
        <button onClick={() => setShowChat(true)} style={{ position: 'fixed', bottom: '30px', right: '30px', width: '60px', height: '60px', background: '#667eea', color: 'white', border: 'none', borderRadius: '50%', fontSize: '28px', cursor: 'pointer', boxShadow: '0 8px 25px rgba(0,0,0,0.3)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>AI</button>
      </main>
      <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
        <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
        <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
